<script setup lang="ts">
import { computed, nextTick, ref } from 'vue'
import { ArrowUpRight, Check, ChevronDown, CircleAlert, ClipboardPaste, Copy, Download, FolderOpen, Link2, LoaderCircle, Minus, Pause, Play, Snowflake, Square, X } from '@lucide/vue'
import UiSelect from './UiSelect.vue'
import { bytes, duration, statusLabels } from '../format'
import { platformLabels } from '../sources'
import type { BatchOptions, DownloadTask, OutputFormat, SourceLink, VideoInfo } from '../types'

const props = defineProps<{ link: string; source: SourceLink | null; video: VideoInfo | null; expanded: boolean; analyzing: boolean; submitting: boolean; quality: number; format: OutputFormat; pages: number[]; options: BatchOptions; tasks: DownloadTask[]; error: string; notice: string; maximized: boolean; clipboardHint: string }>()
const emit = defineEmits<{
  'update:link': [value: string]; 'update:quality': [value: number]; 'update:format': [value: OutputFormat]; 'update:pages': [value: number[]]; 'update:options': [value: BatchOptions]
  analyze: []; submit: []; reset: []; toggle: []; chooseFolder: []; window: [value: 'minimize' | 'maximize' | 'close']; task: [task: DownloadTask, value: 'pause' | 'resume' | 'cancel' | 'reveal']; clipboard: []
}>()
const input = ref<HTMLInputElement>()
const allPages = computed(() => !!props.video && props.video.pages.every(page => props.pages.includes(page.cid)))
function option(key: keyof BatchOptions, value: string | number | boolean) { emit('update:options', { ...props.options, [key]: value }) }
function togglePage(cid: number) { emit('update:pages', props.pages.includes(cid) ? props.pages.filter(item => item !== cid) : [...props.pages, cid]) }
async function focus() { await nextTick(); input.value?.focus() }
defineExpose({ focus })
</script>

<template>
  <section class="minimal-mode" aria-label="简约模式">
    <header class="minimal-header" data-tauri-drag-region>
      <button class="brand minimal-brand" title="切换回完整模式" aria-label="切换回完整模式" @click="emit('toggle')"><span class="brand-mark"><Snowflake :size="23" :stroke-width="1.8" /></span><span>SnowDown<span class="brand-dot">.</span></span></button>
      <div class="window-controls minimal-window-controls"><button aria-label="最小化窗口" title="最小化" @click="emit('window', 'minimize')"><Minus :size="15" /></button><button :aria-label="maximized ? '还原窗口' : '最大化窗口'" :title="maximized ? '还原' : '最大化'" @click="emit('window', 'maximize')"><Copy v-if="maximized" :size="13" /><Square v-else :size="13" /></button><button class="window-close" aria-label="关闭到托盘" title="关闭到托盘，继续下载" @click="emit('window', 'close')"><X :size="17" /></button></div>
    </header>
    <div :class="['minimal-stage', { expanded }]">
      <form class="minimal-input-bar" :aria-busy="analyzing" @submit.prevent="emit('analyze')">
        <Link2 :size="20" class="minimal-link-icon" />
        <input ref="input" :value="link" aria-label="简约视频链接" placeholder="粘贴视频链接，按 Enter 开始" spellcheck="false" autocomplete="off" @input="emit('update:link', ($event.target as HTMLInputElement).value)" />
        <span v-if="source" class="minimal-platform">{{ platformLabels[source.platform] }}</span>
        <button v-if="link || expanded" type="button" class="minimal-clear" aria-label="清空并重新输入" title="重新输入" @click="emit('reset'); focus()"><X :size="16" /></button>
        <button type="submit" class="minimal-parse" aria-label="解析视频" :disabled="analyzing || submitting" :title="analyzing ? '正在解析' : '解析视频'"><LoaderCircle v-if="analyzing" :size="20" class="spin" /><ArrowUpRight v-else :size="21" /></button>
      </form>
      <div v-if="clipboardHint && !expanded" class="minimal-clipboard"><ClipboardPaste :size="13" /><span>{{ clipboardHint }}</span><button @click="emit('clipboard')">使用链接</button></div>
      <div v-if="expanded" class="minimal-body">
        <Transition name="minimal-details" mode="out-in">
          <div v-if="analyzing" key="parsing" class="minimal-loading" role="status"><span class="minimal-loading-line"></span><span class="minimal-loading-line short"></span><p><LoaderCircle :size="14" class="spin" />正在解析{{ source ? platformLabels[source.platform] : '视频' }}链接…</p></div>
          <section v-else-if="video" key="video" class="minimal-result" aria-label="视频下载设置">
            <div class="minimal-video"><img v-if="video.cover" :src="video.cover" alt="视频封面" referrerpolicy="no-referrer" /><span v-else class="minimal-cover"><Snowflake :size="27" /></span><div><small>{{ platformLabels[video.platform] }} · {{ duration(video.duration) }}</small><h1>{{ video.title }}</h1><p>{{ video.author }}</p></div></div>
            <div class="minimal-options">
              <div class="minimal-option"><span>格式</span><div class="minimal-segments" aria-label="下载格式"><button :class="{ selected: format === 'video' }" :aria-pressed="format === 'video'" @click="emit('update:format', 'video')">视频 <small>MP4</small></button><button :class="{ selected: format === 'audio' }" :aria-pressed="format === 'audio'" @click="emit('update:format', 'audio')">音频 <small>M4A</small></button></div></div>
              <div v-if="format === 'video'" class="minimal-option minimal-quality"><span>画质</span><UiSelect :model-value="quality" :options="video.qualities.map(item => ({ value: item.id, label: item.label }))" label="简约视频画质" @update:model-value="value => emit('update:quality', Number(value))" /></div>
              <div class="minimal-option minimal-directory"><FolderOpen :size="16" /><span :title="options.downloadDir">{{ options.downloadDir || '请选择保存位置' }}</span><button @click="emit('chooseFolder')">更改位置<ArrowUpRight :size="12" /></button></div>
              <div class="minimal-attachments"><label><input type="checkbox" :checked="options.saveCover" @change="option('saveCover', ($event.target as HTMLInputElement).checked)" />封面</label><label v-if="video.platform === 'bilibili'"><input type="checkbox" :checked="options.saveDanmaku" @change="option('saveDanmaku', ($event.target as HTMLInputElement).checked)" />弹幕</label><label v-if="video.platform === 'bilibili'"><input type="checkbox" :checked="options.saveSubtitles" @change="option('saveSubtitles', ($event.target as HTMLInputElement).checked)" />字幕</label></div>
            </div>
            <details v-if="video.pages.length > 1" class="minimal-pages"><summary><span>选择分P<small>{{ pages.length }} / {{ video.pages.length }}</small></span><ChevronDown :size="14" /></summary><div class="minimal-pages-top"><button @click="emit('update:pages', allPages ? [] : video.pages.map(page => page.cid))">{{ allPages ? '取消全选' : '全选分P' }}</button></div><div class="minimal-pages-list"><label v-for="page in video.pages" :key="page.cid"><input type="checkbox" :checked="pages.includes(page.cid)" @change="togglePage(page.cid)" /><small>P{{ page.page }}</small><span>{{ page.part }}</span><small>{{ duration(page.duration) }}</small></label></div></details>
            <div class="minimal-download-row"><p v-if="notice" class="minimal-notice" role="status"><Check :size="14" />{{ notice }}</p><span v-else>{{ pages.length }} 项 · 保存到本地</span><button class="button primary" :disabled="submitting || !pages.length" @click="emit('submit')"><LoaderCircle v-if="submitting" :size="16" class="spin" /><Download v-else :size="16" />{{ submitting ? '正在加入队列' : '开始下载' }}</button></div>
          </section>
        </Transition>
        <div v-if="error" class="minimal-error" role="alert"><CircleAlert :size="15" /><span>{{ error }}</span><button :disabled="analyzing || submitting" @click="emit('analyze')">重新解析</button></div>
        <section v-if="tasks.length" class="minimal-downloads" aria-label="下载进度"><header><span>下载队列</span><small>{{ tasks.length }} 项</small></header><article v-for="task in tasks" :key="task.id" class="minimal-task"><div class="minimal-task-heading"><strong :title="`${task.title} · ${task.pageTitle}`">{{ task.pageTitle || task.title }}</strong><span>{{ statusLabels[task.status] }}<template v-if="task.status === 'downloading'"> · {{ Math.min(100, task.progress).toFixed(1) }}%</template></span><button v-if="['queued', 'downloading'].includes(task.status)" aria-label="暂停下载" @click="emit('task', task, 'pause')"><Pause :size="14" /></button><button v-else-if="['paused', 'failed'].includes(task.status)" aria-label="继续下载" @click="emit('task', task, 'resume')"><Play :size="14" /></button><button v-else-if="task.status === 'completed'" aria-label="定位已下载文件" @click="emit('task', task, 'reveal')"><FolderOpen :size="14" /></button></div><div class="minimal-task-progress" role="progressbar" :aria-label="`${task.pageTitle || task.title}下载进度`" :aria-valuenow="Math.round(Math.min(100, task.progress))" aria-valuemin="0" aria-valuemax="100"><span :style="{ width: `${Math.min(100, task.progress)}%` }"></span></div><p v-if="task.error" class="minimal-task-error">{{ task.error }}</p><p v-else><span>{{ bytes(task.downloadedBytes) }}<template v-if="task.totalBytes"> / {{ bytes(task.totalBytes) }}</template></span><span v-if="task.status === 'downloading'">{{ bytes(task.speed) }}/s</span><span v-else-if="task.status === 'completed'">已保存</span></p></article></section>
      </div>
    </div>
  </section>
</template>

<style scoped>
