er-radius:10px}.minimal-body{position:absolute;inset:112px 0 0;overflow-y:auto;padding:0 max(48px,calc((100% - 800px)/2)) 36px;scrollbar-gutter:stable;animation:minimal-body-in .5s .15s both}.minimal-video{display:flex;align-items:center;gap:19px;padding:6px 0 24px}.minimal-video>img,.minimal-cover{width:138px;height:88px;flex-shrink:0;border-radius:12px;object-fit:cover;background:#edf4fc}.minimal-cover{display:flex;align-items:center;justify-content:center;color:#9dbce5}.minimal-video>div{min-width:0}.minimal-video small{font-size:10px;color:#98a8bc}.minimal-video h1{font-size:19px;letter-spacing:-.4px;line-height:1.6;margin:7px 0 4px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.minimal-video p{font-size:11px;color:#8f9fb4;margin:0}.minimal-options{display:grid;grid-template-columns:1fr 1fr;gap:21px 32px;padding:23px 0;border-top:1px solid #e6edf5;border-bottom:1px solid #e6edf5}.minimal-option{display:flex;align-items:center;gap:19px;min-width:0}.minimal-option>span:first-child{font-size:11px;color:#92a2b8;flex-shrink:0}.minimal-segments{display:flex;background:#eff3f9;padding:3px;border-radius:8px;gap:2px}.minimal-segments button{padding:7px 13px;border-radius:6px;background:transparent;font-size:11px;color:#96a4b8}.minimal-segments button.selected{background:#fff;color:#4f83cc;box-shadow:0 1px 4px #3c5b8a0b}.minimal-segments small{font-size:8px;margin-left:4px;opacity:.65}.minimal-quality :deep(.ui-select){flex:1;min-width:0}.minimal-directory{grid-column:1/-1;gap:9px;color:#9aacc3}.minimal-directory>span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px;color:#879cb8}.minimal-directory button{display:flex;align-items:center;gap:4px;background:transparent;color:#7797c0;font-size:10px;flex-shrink:0}.minimal-attachments{grid-column:1/-1;display:flex;gap:24px}.minimal-attachments label{display:flex;align-items:center;gap:7px;color:#8c9db4;font-size:11px;cursor:pointer}.minimal-attachments input{width:13px;height:13px;min-width:13px}.minimal-pages{border-bottom:1px solid #e6edf5;font-size:11px;color:#7f93af}.minimal-pages summary{list-style:none;display:flex;justify-content:space-between;align-items:center;padding:17px 0;cursor:pointer}.minimal-pages summary::-webkit-details-marker{display:none}.minimal-pages summary small{font-size:10px;color:#a5b2c3;margin-left:9px}.minimal-pages[open] summary>svg{transform:rotate(180deg)}.minimal-pages-top{display:flex;justify-content:flex-end;margin-bottom:8px}.minimal-pages-top button{background:transparent;color:#769ad0;font-size:10px}.minimal-pages-list{max-height:154px;overflow-y:auto;margin-bottom:14px}.minimal-pages-list label{display:flex;align-items:center;gap:9px;padding:10px 1px;cursor:pointer}.minimal-pages-list label>span{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.minimal-pages-list small{color:#a6b4c6;font-size:9px}.minimal-download-row{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:22px 0}.minimal-download-row>span{font-size:10px;color:#9aaac0}.minimal-download-row .button{padding:10px 22px;border-radius:9px;font-size:12px}.minimal-notice{display:flex;gap:6px;align-items:center;font-size:10px;color:#78a48e;margin:0}.minimal-loading{padding:16px 0 35px}.minimal-loading-line{display:block;width:65%;height:13px;border-radius:7px;background:#eaf0f7;animation:minimal-pulse 1.6s ease-in-out infinite}.minimal-loading-line.short{width:38%;margin-top:18px;height:9px}.minimal-loading p{display:flex;align-items:center;gap:8px;font-size:11px;color:#8fa5c1;margin-top:28px}.minimal-error{display:flex;align-items:flex-start;gap:8px;font-size:11px;color:#b3827e;line-height:1.9;padding:18px 0}.minimal-error span{flex:1;overflow-wrap:anywhere}.minimal-error svg{margin-top:3px}.minimal-error button{color:#7198ce;background:transparent;white-space:nowrap;font-size:10px}.minimal-downloads{margin-top:6px;border-top:1px solid #e6edf5;padding-top:19px